struct nglListNode;

struct Pair {
    nglListNode *first;
    unsigned int second;
};

class nglOpaqueCompare {
public:
    bool operator()(const Pair &a, const Pair &b) {
        return a.second < b.second;
    }
};

extern "C" void partial_sort_impl(Pair *, Pair *, Pair *, Pair *, Pair *,
                                  nglOpaqueCompare)
    __asm__("__partial_sort__H3ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZ16nglOpaqueCompare_X01X01X01PX11X21_v");
extern "C" Pair *unguarded_partition_impl(Pair *, Pair *, const Pair &,
                                           nglOpaqueCompare)
    __asm__("__unguarded_partition__H3ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZ16nglOpaqueCompare_X01X01X11X21_X01");

static const Pair &median_impl(const Pair &a, const Pair &b, const Pair &c,
                               nglOpaqueCompare comp) {
    if (comp(a, b))
        if (comp(b, c))
            return b;
        else if (comp(a, c))
            return c;
        else
            return a;
    else if (comp(a, c))
        return a;
    else if (comp(b, c))
        return c;
    else
        return b;
}

extern "C" void introsort_loop_impl(Pair *, Pair *, Pair *, int,
                                    nglOpaqueCompare)
    __asm__("__introsort_loop__H4ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZiZ16nglOpaqueCompare_X01X01PX11X21X31_v");
void introsort_loop_impl(Pair *first, Pair *last, Pair *, int depth_limit,
                         nglOpaqueCompare comp) {
    while (last - first > 16) {
        if (depth_limit == 0) {
            partial_sort_impl(first, last, last, (Pair *)0, (Pair *)0, comp);
            return;
        }
        --depth_limit;
        Pair *cut = unguarded_partition_impl(
            first, last,
            Pair(median_impl(*first, *(first + (last - first) / 2),
                             *(last - 1), comp)),
            comp);
        introsort_loop_impl(cut, last, (Pair *)0, depth_limit, comp);
        last = cut;
    }
}
